func (v StatusValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var supportedModelsVal basetypes.ListValue
	switch {
	case v.SupportedModels.IsUnknown():
		supportedModelsVal = types.ListUnknown(types.StringType)
	case v.SupportedModels.IsNull():
		supportedModelsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		supportedModelsVal, d = types.ListValue(types.StringType, v.SupportedModels.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"connected":    basetypes.BoolType{},
			"error":        basetypes.StringType{},
			"last_checked": basetypes.StringType{},
			"supported_models": basetypes.ListType{
				ElemType: types.StringType,
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"connected":    basetypes.BoolType{},
		"error":        basetypes.StringType{},
		"last_checked": basetypes.StringType{},
		"supported_models": basetypes.ListType{
			ElemType: types.StringType,
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"connected":        v.Connected,
			"error":            v.Error,
			"last_checked":     v.LastChecked,
			"supported_models": supportedModelsVal,
		})

	return objVal, diags
}

